# Simulate the logic: eye(6).col_insert(3, ones(6,2)*2)
# Original: 6x6, other: 6x2, pos=3
# Result should be 6x8
pos = 3
other_cols = 2
self_cols = 6

def entry(i, j):
    if j < pos:
        return 'self[%d,%d]' % (i, j)
    elif pos <= j < pos + other_cols:
        return 'other[%d,%d]' % (i, j - pos)
    return 'self[%d,%d]' % (i, j - other_cols)

for i in range(6):
    row = []
    for j in range(8):
        row.append(entry(i, j))
    print(row)
"

